using System;
using System.Reflection;
using System.Linq;

var dlls = new[] {
    "/home/runner/.nuget/packages/microsoft.agents.ai/1.10.0/lib/net10.0/Microsoft.Agents.AI.dll",
    "/home/runner/.nuget/packages/microsoft.extensions.ai/10.6.0/lib/net10.0/Microsoft.Extensions.AI.dll"
};

foreach (var dllPath in dlls)
{
    Console.WriteLine($"\n{'='*80}");
    Console.WriteLine($"PUBLIC API: {System.IO.Path.GetFileName(dllPath)}");
    Console.WriteLine($"{'='*80}\n");

    var asm = Assembly.LoadFrom(dllPath);
    var pubTypes = asm.GetTypes()
        .Where(t => (t.IsPublic || (t.IsNestedPublic && !t.IsCompilerGenerated())) && !t.Name.Contains('<'))
        .OrderBy(t => t.Namespace)
        .ThenBy(t => t.Name);

    foreach (var type in pubTypes)
    {
        var baseInfo = "";
        if (type.BaseType != null && type.BaseType != typeof(object))
            baseInfo = $" : {type.BaseType.Name}";

        var interfaces = type.GetInterfaces()
            .Where(i => !i.Name.StartsWith("I") || i.Namespace?.StartsWith("System.Collections") != true)
            .Take(3);
        var ifaceStr = interfaces.Any() ? $" implements {string.Join(", ", interfaces.Select(i => i.Name))}" : "";

        Console.WriteLine($"{type.Namespace}.{type.Name}{baseInfo}{ifaceStr}");

        // Show constructors
        var ctors = type.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        if (ctors.Length > 0)
        {
            foreach (var ctor in ctors)
            {
                var @params = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
                Console.WriteLine($"  .ctor({@params})");
            }
        }

        // Show public methods
        var methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static)
            .Where(m => !m.IsSpecialName && !m.IsCompilerGenerated())
            .OrderBy(m => m.Name)
            .Take(15);

        foreach (var method in methods)
        {
            var retType = method.ReturnType.Name;
            var @params = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  {retType} {method.Name}({@params})");
        }

        // Show public properties
        var props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => !p.IsCompilerGenerated())
            .OrderBy(p => p.Name)
            .Take(10);

        if (props.Any())
        {
            foreach (var prop in props)
            {
                var accessors = "";
                if (prop.CanRead) accessors += "get;";
                if (prop.CanWrite) accessors += "set;";
                Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name} {{ {accessors} }}");
            }
        }

        Console.WriteLine();
    }
}
