using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (
        [Description("The search query to look up on the web")] string query
    ) =>
    {
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        return WebSearchSimulator.SearchAsync(query);
    },
    "web_search",
    "Search the web for information on a topic. Returns a list of result snippets.");

var addNoteTool = AIFunctionFactory.Create(
    (
        [Description("Short label for the note")] string title,
        [Description("The content to save")] string content
    ) =>
    {
        notebook.Add(title, content);
        Console.WriteLine($"  📝  Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully.";
    },
    "add_note",
    "Save a research note for later reference when writing the summary.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        var notes = notebook.ReadAll();
        Console.WriteLine($"  📖  Reading {notebook.Count} note(s)");
        return notes;
    },
    "read_notes",
    "Read all saved research notes collected so far.");

// --- Build the chat client with automatic function invocation ----------------

IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Create the agent --------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic you must:
        1. Use the web_search tool multiple times with varied queries to gather
           diverse information about the topic.
        2. Use add_note to save key findings as you go.
        3. After gathering enough information, use read_notes to review everything.
        4. Finally, write a well-structured summary with sections, key facts, and
           source references.
        Be thorough — make at least 3 different searches before summarizing.
        """,
    name: "ResearchAgent",
    tools: [searchTool, addNoteTool, readNotesTool]);

// --- Run ---------------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔬 AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "the impact of quantum computing on cryptography";

Console.WriteLine();
Console.WriteLine($"Researching: \"{topic}\"");
Console.WriteLine(new string('─', 50));

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.WriteLine("📋  RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine();

var chatResponse = response.AsChatResponse();
Console.WriteLine(chatResponse.Text);

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Notes collected: {notebook.Count}");
Console.WriteLine($"Tokens used: {chatResponse.Usage?.TotalTokenCount ?? 0}");

// =============================================================================
// Supporting types
// =============================================================================

/// <summary>Thread-safe in-memory notebook for the agent's research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];
    private readonly Lock _lock = new();

    public int Count { get { lock (_lock) return _notes.Count; } }

    public void Add(string title, string content)
    {
        lock (_lock) _notes.Add((title, content));
    }

    public string ReadAll()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
                return "(no notes yet)";

            return string.Join("\n\n", _notes.Select((n, i) =>
                $"[Note {i + 1}: {n.Title}]\n{n.Content}"));
        }
    }
}

/// <summary>
/// Simulated web search that returns plausible results.
/// Replace with a real search API (Bing, Google, Tavily) for production use.
/// </summary>
static class WebSearchSimulator
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Try a real fetch from Wikipedia's API for grounded results.
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=3&utf8=&format=json";
            var json = await Http.GetStringAsync(url);

            // Extract snippet text from the JSON (lightweight parsing).
            var snippets = new List<string>();
            var searchResults = System.Text.Json.JsonDocument.Parse(json);
            if (searchResults.RootElement.TryGetProperty("query", out var q) &&
                q.TryGetProperty("search", out var results))
            {
                foreach (var result in results.EnumerateArray())
                {
                    var title = result.GetProperty("title").GetString();
                    var snippet = result.GetProperty("snippet").GetString();
                    // Strip HTML tags from Wikipedia snippets
                    snippet = System.Text.RegularExpressions.Regex.Replace(
                        snippet ?? "", "<.*?>", "");
                    snippets.Add($"• {title}: {snippet}");
                }
            }

            return snippets.Count > 0
                ? $"Search results for \"{query}\":\n{string.Join("\n", snippets)}"
                : $"No results found for \"{query}\".";
        }
        catch
        {
            return $"Search results for \"{query}\":\n"
                 + "• (Search unavailable — please check network connectivity)";
        }
    }
}

